import os,csv
import matplotlib.pyplot as plt
out='/output';os.makedirs(out,exist_ok=True)
rows=[
('合并净利润',8463710355.65,10284306198.28,'利润起点'),('资产减值准备',4675845573.44,1525699477.87,'非现金调整'),('信用减值损失',555019707.28,160477312.83,'非现金调整'),('固定资产等折旧',4055643135.37,3900295097.42,'非现金调整/持续经营'),('使用权资产摊销',146790888.18,151581488.10,'非现金调整/持续经营'),('无形资产摊销',268693885.32,235202257.14,'非现金调整/持续经营'),('长期待摊费用摊销',140620901.18,144262757.84,'非现金调整/持续经营'),('长期资产处置损失（收益）',15203668.87,61496104.10,'非现金/损益调整'),('固定资产报废损失',42089507.17,23415123.64,'非现金/损益调整'),('公允价值变动损失（收益）',28153114.85,-278186201.65,'非现金/损益调整'),('财务费用（收益）',1026190054.25,2224989299.63,'利润非经营性调节'),('投资损失（收益）',-2417330849.26,31088785.68,'投资收益/损益重分类'),('递延所得税资产减少（增加）',-388802754.25,-208817859.08,'非现金调整'),('递延所得税负债增加（减少）',25513908.30,124635685.72,'非现金调整'),('存货减少（增加）',585324717.44,1789456605.89,'营运资金'),('经营性应收项目减少（增加）',1824572724.85,-260526292.91,'营运资金'),('经营性应付项目增加（减少）',2611147936.03,-1751369897.44,'营运资金'),('其他',81353918.71,132351707.50,'其他'),('经营活动产生的现金流量净额',21739740393.38,18290357650.56,'核对合计')]
rows=[(n,a/1e6,b/1e6,c) for n,a,b,c in rows]
with open(out+'/cash_bridge_detail.csv','w',newline='',encoding='utf-8-sig') as f:
 w=csv.writer(f);w.writerow(['项目','2024金额_人民币百万元','2023金额_人民币百万元','同比变动_人民币百万元','分类','来源']);
 for n,a,b,c in rows:w.writerow([n,f'{a:.6f}',f'{b:.6f}',f'{a-b:.6f}',c,'伊利股份2024年年度报告；合并现金流量表补充资料，物理页217-218'])
net=rows[-1][1]-rows[-1][2]
# contribution buckets without overlap
agg=[('合并净利润',rows[0][1]-rows[0][2]),('资产及信用减值准备',sum(rows[i][1]-rows[i][2] for i in [1,2])),('折旧摊销、处置报废、公允价值及递延税',sum(rows[i][1]-rows[i][2] for i in [3,4,5,6,7,8,9,12,13])),('财务费用调整',rows[10][1]-rows[10][2]),('投资收益重分类',rows[11][1]-rows[11][2]),('营运资金净贡献',sum(rows[i][1]-rows[i][2] for i in [14,15,16])),('其他',rows[17][1]-rows[17][2])]
fig,ax=plt.subplots(figsize=(12,6)); start=rows[-1][2]; cur=start
for i,(lab,val) in enumerate(agg):
 ax.bar(i,val,bottom=cur if val>=0 else cur+val,color='#2e8b57' if val>=0 else '#c44e52',width=.68)
 ax.text(i,cur+val+(120 if val>=0 else -120),f'{val:+,.0f}',ha='center',va='bottom' if val>=0 else 'top',fontsize=8);cur+=val
ax.bar(len(agg),net,bottom=start,color='#4c72b0',width=.68);ax.text(len(agg),start+net+200,f'{net:+,.0f}',ha='center',fontsize=9)
ax.axhline(start,color='gray',ls='--',lw=.8);ax.set_xticks(range(len(agg)+1));ax.set_xticklabels([x[0] for x in agg]+['CFO净增'],rotation=22,ha='right');ax.set_ylabel('人民币百万元');ax.set_title('伊利2024经营现金流同比增加的调节贡献（合并口径）');fig.tight_layout();fig.savefig(out+'/cashflow_contribution.png',dpi=180);plt.close(fig)
open(out+'/recompute.py','w',encoding='utf-8').write('''import csv\nfrom decimal import Decimal\nrows=list(csv.DictReader(open("cash_bridge_detail.csv",encoding="utf-8-sig")))\nfor r in rows: print(r["项目"], Decimal(r["2024金额_人民币百万元"])-Decimal(r["2023金额_人民币百万元"]))\nprint("bridge delta",sum(Decimal(r["2024金额_人民币百万元"])-Decimal(r["2023金额_人民币百万元"]) for r in rows[:-1]))\nprint("reported CFO delta",Decimal(rows[-1]["2024金额_人民币百万元"])-Decimal(rows[-1]["2023金额_人民币百万元"]))\n''')
report='''# 伊利股份2024盈利与经营现金流：现金桥分析\n\n## 简洁结论\n经营现金流净额同比增加 **3,449.383百万元（+18.86%）**，尽管合并净利润减少 **1,820.596百万元**。现金桥显示，营运资金相关项目同比改善 **5,243.485百万元**，资产及信用减值准备调节同比增加 **3,544.689百万元**；投资收益相关重分类贡献变化 **-2,448.420百万元**（负数表示减少现金桥调节值）。所以现金转化表面改善，但不能单独断言经常性盈利质量全面改善：改善较多来自营运资金释放及非现金减值加回，持续性需审慎。\n\n## 关键数值（人民币百万元）\n|项目|2024|2023|同比变动|\n|---|---:|---:|---:|\n|合并净利润|8,463.710|10,284.306|-1,820.596|\n|经营活动现金流净额|21,739.740|18,290.358|+3,449.383|\n|资产减值准备|4,675.846|1,525.699|+3,150.146|\n|信用减值损失|555.020|160.477|+394.542|\n|营运资金合计（存货+经营性应收+经营性应付）|5,021.045|-222.439|+5,243.485|\n|投资损失（收益以负号填列）|-2,417.331|31.089|-2,448.420|\n\n数额为人民币百万元，比例另列：经营现金流同比 **+18.86%**；归母净利润同比 **-18.94%**；扣非归母净利润同比 **-40.04%**。百分点是比例变动单位，不适用于金额变化。\n\n## 同比贡献解读\n- **减值等非现金项目**：资产减值准备增加贡献 +3,150.146，信用减值损失增加贡献 +394.542；两者合计+3,544.689。减值加回增加能抬高间接法CFO，但本身说明当期损益承压，不等于盈利改善。折旧摊销、处置/报废、公允价值、递延税等逐项见CSV。\n- **营运资金释放**：存货减少的现金桥贡献较上年减少1,204.132；经营性应收项目贡献增加2,085.099；经营性应付项目贡献增加4,362.518。合计同比改善5,243.485。此为现金流量表补充资料列示的聚合值，可能受回款/付款时点影响，不应推定为可持续水平。\n- **投资收益**：补充资料“投资损失（收益以‘－’号填列）”由2023年+31.089变为2024年-2,417.331，同比-2,448.420。2024投资收益在净利润转CFO时作为扣减，这一变化是重要调节项，不是经营现金流本身的现金贡献。\n- **持续经营因素**：净利润下降本身拖累1,820.596；折旧摊销、财务费用等会计调节及经营收付共同形成最终CFO。仅凭该调节表无法把每项都归因于业务经营质量。\n\n## 归母、扣非归母另列（不代入合并现金桥）\n2024归母净利润为8,452.860，2023为10,428.540，同比-18.94%；2024扣非归母为6,011.275，2023为10,026.171，同比-40.04%。现金流补充资料的起点是**合并净利润**8,463.710 / 10,284.306，故归母或扣非归母均不能替代现金桥起点。\n\n## 来源、口径与局限\n- 来源文件：伊利股份2024年年度报告，document_id `d84573bf6b584e7e874faa4c6adf454a`。合并现金流量表补充资料物理页217-218（印刷页213-214，t253及续页）；合并现金流量表物理页94（t107）；归母净利润物理页7，扣非归母物理页8、82（t8/t10/t97）。原披露单位人民币元，本分析统一除以1,000,000转换为人民币百万元。\n- 同比贡献按各行2024金额减2023金额；经营现金流净额为核对终点，现金桥合计变动与其同比变动一致，约3,449.383百万元。\n- 间接法调节项目是会计调节，不等同因果或现金来源归因。经营性应收/应付披露为聚合项目，未给出本表可核实的组成与时点细节。减值加回不能解释为损失已转回。\n- 仅用两年数据和所给年报，不能验证营运资金变化的可持续性，也不足以形成全面盈利质量结论。\n\n## 图表\n![现金流贡献图](cashflow_contribution.png)\n\n明细见 `cash_bridge_detail.csv`；复算脚本 `recompute.py` 可核验各行同比变化和合计。\n'''
open(out+'/report.md','w',encoding='utf-8').write(report)
print('delta',net,'sum components',sum(v for _,v in agg),'wc',agg[5][1])